SHORT = {'andrii_f': 'andrii', 'polievkt': 'polievkt', 'illia_im': 'illia', 'r6_ioann_o2': 'ioann', 'r6_leontii_k': 'leontii', 'yakiv_an': 'yakiv',
         'r6_danyil_a': 'danyil', 'g20_antonii': 'antonii', 'g20_havrylo_h': 'havrylo', 'g20_stefan_d': 'stefan', 'r24_kyrylo': 'kyrylo', 'trokhym_per': 'trokhym'}
new = []
for pid, recs, title, date, line, text, wf, app in D:
    did = 'gw811' + SHORT[pid]
    files, marks = [], []
    for i, (rec, t, mk) in enumerate(recs):
        fn = '%s_%d.jpg' % (did, rec); put(rec, fn); files.append({'file': fn, 'thumb': fn.replace('.jpg', '-t.jpg')}); marks.append({'p': i, **mk})
    if did not in have:
        new.append({'key': did, 'kind': 'doc', 'id': did, 'files': files, 'data': {'title': title, 'date': date, 'place': 'Чернігівська губ., Козелецький пов.',
            'src': ARCH + '. Записи: ' + ', '.join(str(r[0]) for r in recs) + '.', 'url': G + recs[0][1] + str(recs[0][0]) + '/',
            'line': line, 'text': text + ' Інші записи: ' + ', '.join(G + t + str(r) + '/' for r, t, _ in recs[1:]) if len(recs) > 1 else text,
            'people': [pid], 'marks': marks}})
    k = 'gw811-pp-' + pid
    if k not in have:
        pp = {'key': k, 'kind': 'personpatch', 'person': pid, 'append': app}
        if pid not in ('andrii_f', 'polievkt'): pp['set'] = {'war': {'w': 'ww1', 'f': wf, 'h': True}}
        new.append(pp)
m.extend(new); json.dump(m, open(MAN, 'w'), ensure_ascii=False, indent=1); print('додано', len(new))
